CAT = "ea1Specialized"; SEG = "SPR"
# Specialized returns for individuals (SEE Part 1 domain 6): estate, gift, international reporting.
# 2025 figures cited in sources.md (IRS, What's new: estate and gift tax).
_jt = 600000 * 70 // 100; assert _jt == 420000
_te = 16000000 - 500000 - 1000000 - 2000000; assert _te == 12500000
_529 = 5 * 19000; assert _529 == 95000

